head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > M > getDisplayFormatter]<br/>컴포넌트의 displayFormatter 속성값을 반환합니다.",
    "validation" : [
        "컴포넌트의 displayFormatter 속성에 설정된 사용자 함수의 이름을 반환합니다.",
        "displayFormatter 속성을 설정하지 않은 경우 ''(Empty String)이 반환됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.get_text = function(target) {    
    let rtn = '';
    let tagName = target.render.tagName

    if (tagName !== "INPUT") {
        rtn = target.render.textContent
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);    
    }
    else {
        rtn = target.render.value
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);   
    }    
}



scwin.get_displayFormatter = function(target) {   
    let rtn = '';
    rtn = target.getDisplayFormatter();

     wf_body_bottom.getObj("scwin").setReturnValue("getDisplayFormatter : " + rtn);   
}



 // 사용자 정의 함수
 scwin.fn_dpformatter = function(val) {
    return "language -> " + val;
 };



// target1
scwin.btn_setDisplayFormatter1_onclick = function (e) {
    target1.setDisplayFormatter("scwin.fn_dpformatter");
    target1.setValue("langkoKR");
    // target1.focus();
};

scwin.btn_getDisplayFormatter1_onclick = function (e) {
    scwin.get_displayFormatter(target1);
};

// target2
scwin.btn_setDisplayFormatter2_onclick = function (e) {    
    target2.setDisplayFormatter("scwin.fn_dpformatter");
    target2.setValue("langkoKR");
    // target1.focus();
};

scwin.btn_getDisplayFormatter2_onclick = function (e) {
    scwin.get_displayFormatter(target2);
};

// target3 - displayFormatter 미설정, 기대값=''
scwin.btn_getDisplayFormatter3_onclick = function (e) {
    scwin.get_displayFormatter(target3);
};


scwin.btn_setAll_onclick = function (e) {
    // target3은 displayFormatter 미설정 검증용이므로 setAll에서 제외
    for (var i = 1; i < 3; i ++)
        eval("scwin.btn_setDisplayFormatter"+i+"_onclick()");
}

scwin.btn_getAll_onclick = function (e) {
    for (var i = 1; i < 4; i ++)
        eval("scwin.btn_getDisplayFormatter"+i+"_onclick()");
};
